/* eslint-disable no-useless-escape */

'use strict';

// MODULES //

var tape = require( 'tape' );
var resolve = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof resolve, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if the first argument is not an object or array', function test( t ) {
	var values;
	var i;

	values = [
		'abc',
		5,
		NaN,
		true,
		null,
		void 0,
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			resolve( value, '/foo' );
		};
	}
});

tape( 'the function throws an error if the second argument is not a string', function test( t ) {
	var values;
	var doc;
	var i;

	doc = {
		'foo': 'bar'
	};
	values = [
		5,
		NaN,
		true,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			resolve( doc, value );
		};
	}
});

tape( 'the function returns the root document for an empty pointer', function test( t ) {
	var doc;
	var out;

	doc = {
		'foo': 'bar'
	};
	out = resolve( doc, '' );

	t.strictEqual( out.target, null, 'returns expected value' );
	t.strictEqual( out.key, null, 'returns expected value' );
	t.strictEqual( out.value, doc, 'returns expected value' );
	t.end();
});

tape( 'the function resolves pointers on objects', function test( t ) {
	var expected;
	var values;
	var doc;
	var out;
	var i;

	doc = {
		'foo': [ 'bar', 'baz' ],
		'': 0,
		'a/b': 1,
		'c%d': 2,
		'e^f': 3,
		'g|h': 4,
		'i\\j': 5,
		'k\"l': 6,
		' ': 7,
		'm~n': 8
	};

	values = [
		'/foo',
		'/',
		'/a~1b',
		'/c%d',
		'/e^f',
		'/g|h',
		'/i\\j',
		'/k\"l',
		'/ ',
		'/m~0n'
	];
	expected = [
		{
			'key': 'foo',
			'value': doc.foo
		},
		{
			'key': '',
			'value': 0
		},
		{
			'key': 'a/b',
			'value': 1
		},
		{
			'key': 'c%d',
			'value': 2
		},
		{
			'key': 'e^f',
			'value': 3
		},
		{
			'key': 'g|h',
			'value': 4
		},
		{
			'key': 'i\\j',
			'value': 5
		},
		{
			'key': 'k\"l',
			'value': 6
		},
		{
			'key': ' ',
			'value': 7
		},
		{
			'key': 'm~n',
			'value': 8
		}
	];

	for ( i = 0; i < values.length; i++ ) {
		out = resolve( doc, values[ i ] );
		t.strictEqual( out.target, doc, 'returns expected value' );
		t.strictEqual( out.key, expected[ i ].key, 'returns expected value' );
		t.deepEqual( out.value, expected[ i ].value, 'returns expected value' );
	}
	t.end();
});

tape( 'the function resolves pointers on arrays', function test( t ) {
	var doc;
	var out;

	doc = {
		'foo': [ 'bar', 'baz', 'qux' ]
	};

	out = resolve( doc, '/foo/0' );
	t.strictEqual( out.target, doc.foo, 'returns expected value' );
	t.strictEqual( out.key, 0, 'returns expected value' );
	t.strictEqual( out.value, 'bar', 'returns expected value' );

	out = resolve( doc, '/foo/1' );
	t.strictEqual( out.target, doc.foo, 'returns expected value' );
	t.strictEqual( out.key, 1, 'returns expected value' );
	t.strictEqual( out.value, 'baz', 'returns expected value' );

	out = resolve( doc, '/foo/2' );
	t.strictEqual( out.target, doc.foo, 'returns expected value' );
	t.strictEqual( out.key, 2, 'returns expected value' );
	t.strictEqual( out.value, 'qux', 'returns expected value' );
	t.end();
});

tape( 'the function resolves nested pointers', function test( t ) {
	var doc;
	var out;

	doc = {
		'a': {
			'b': {
				'c': 42
			}
		}
	};

	out = resolve( doc, '/a/b/c' );
	t.strictEqual( out.target, doc.a.b, 'returns expected value' );
	t.strictEqual( out.key, 'c', 'returns expected value' );
	t.strictEqual( out.value, 42, 'returns expected value' );
	t.end();
});

tape( 'the function resolves the `-` token on arrays to the past-the-end index', function test( t ) {
	var doc;
	var out;

	doc = {
		'foo': [ 'a', 'b', 'c' ]
	};

	out = resolve( doc, '/foo/-' );
	t.strictEqual( out.target, doc.foo, 'returns expected value' );
	t.strictEqual( out.key, 3, 'returns expected value' );
	t.strictEqual( out.value, void 0, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error for unsafe tokens', function test( t ) {
	var values;
	var doc;
	var i;

	doc = {
		'foo': {
			'bar': 1
		}
	};
	values = [
		'/__proto__',
		'/constructor',
		'/prototype',
		'/foo/__proto__',
		'/foo/constructor'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			resolve( doc, value );
		};
	}
});

tape( 'the function throws an error for nonexistent object properties', function test( t ) {
	var doc;

	doc = {
		'foo': 'bar'
	};
	t.throws( function badValue() {
		resolve( doc, '/missing' );
	}, Error, 'throws an error when provided /missing' );
	t.end();
});

tape( 'the function throws an error for out-of-bounds array indices', function test( t ) {
	var doc;

	doc = {
		'foo': [ 1, 2, 3 ]
	};
	t.throws( function badValue() {
		resolve( doc, '/foo/5' );
	}, RangeError, 'throws an error when provided /foo/5' );
	t.end();
});

tape( 'the function throws an error for invalid array indices', function test( t ) {
	var values;
	var doc;
	var i;

	doc = {
		'foo': [ 1, 2, 3 ]
	};
	values = [
		'/foo/01',
		'/foo/bar',
		'/foo/-1',
		'/foo/1.5'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			resolve( doc, value );
		};
	}
});

tape( 'the function throws an error when traversing into a primitive', function test( t ) {
	var doc;

	doc = {
		'foo': 'bar'
	};
	t.throws( function badValue() {
		resolve( doc, '/foo/baz' );
	}, TypeError, 'throws an error when traversing into a string' );

	doc = {
		'foo': 42
	};
	t.throws( function badValue() {
		resolve( doc, '/foo/bar' );
	}, TypeError, 'throws an error when traversing into a number' );
	t.end();
});
